// Domain/Repositories/IAsyncClockEntryRepository.cs
public interface IAsyncClockEntryRepository
{
    Task SaveClockEntryAsync(ClockEntry clockEntry, CancellationToken cancellationToken = default);
    Task<ClockEntry?> GetOpenClockEntryAsync(int employeeId, CancellationToken cancellationToken = default);
}

// Infrastructure/ClockEntryEntity.cs
public sealed class ClockEntryEntity
{
    public int Id { get; set; }
    public int EmployeeId { get; set; }
    public DateTime ClockIn { get; set; }
    public DateTime? Clockout { get; set; }
}

// Infrastructure/TimeClockDbContext.cs
using Microsoft.EntityFrameworkCore;
public sealed class TimeClockDbContext : DbContext
{
    public TimeClockDbContext(DbContextOptions<TimeClockDbContext> options) : base(options) { }
    public DbSet<ClockEntryEntity> ClockEntries => Set<ClockEntryEntity>();
}

// Infrastructure/EfClockEntryRepository.cs
using Microsoft.EntityFrameworkCore;
public sealed class EfClockEntryRepository : IAsyncClockEntryRepository
{
    private readonly TimeClockDbContext _dbContext;
    public EfClockEntryRepository(TimeClockDbContext dbContext) { _dbContext = dbContext; }
    public async Task SaveClockEntryAsync(ClockEntry clockEntry, CancellationToken cancellationToken = default)
    {
        ClockEntryEntity entity = new() { EmployeeId = clockEntry.EmployeeId, ClockIn = clockEntry.ClockIn, Clockout = clockEntry.Clockout };
        _dbContext.ClockEntries.Add(entity);
        await _dbContext.SaveChangesAsync(cancellationToken);
    }
    public async Task<ClockEntry?> GetOpenClockEntryAsync(int employeeId, CancellationToken cancellationToken = default)
    {
        ClockEntryEntity? entity = await _dbContext.ClockEntries.AsNoTracking().FirstOrDefaultAsync(item => item.EmployeeId == employeeId && item.Clockout == null, cancellationToken);
        if (entity is null) return null;
        return new ClockEntry(entity.EmployeeId, entity.ClockIn);
    }
}

// Domain/Services/AsyncClockEntryService.cs
public sealed class AsyncClockEntryService
{
    private readonly IAsyncClockEntryRepository _repository;
    public AsyncClockEntryService(IAsyncClockEntryRepository repository) { _repository = repository; }
    public async Task<bool> TryClockInAsync(int employeeId, DateTime clockInTime, CancellationToken cancellationToken = default)
    {
        ClockEntry? open = await _repository.GetOpenClockEntryAsync(employeeId, cancellationToken);
        if (open is not null) return false;
        await _repository.SaveClockEntryAsync(new ClockEntry(employeeId, clockInTime), cancellationToken);
        return true;
    }
}
